// map = { type: "linear" | "sphere" | "cylinder" | "points",
//         axis: 0|1|2 (linear direction / cylinder axis), centre: [x,y,z] (sphere, cylinder),
//         flip: bool, smooth: bool, curve, count,
//         points: [{ p: [x,y,z], v: % }], blend: 1..6 (points: higher = each point holds its value further) }
