  for (let i = 0; i < seg; i++) { const j = (i + 1) % seg; t.push(oA + i, oA + j, oB + j, oA + i, oB + j, oB + i); }
  if (r0 > 1e-6) {
    const iA = ring(r0, a), iB = ring(r0, b);
    for (let i = 0; i < seg; i++) {
      const j = (i + 1) % seg;
      t.push(iA + i, iB + j, iA + j, iA + i, iB + i, iB + j);          // inner wall faces the axis
      t.push(oA + i, iA + j, oA + j, oA + i, iA + i, iA + j);          // cap at a faces -ax
      t.push(oB + i, oB + j, iB + j, oB + i, iB + j, iB + i);          // cap at b faces +ax
    }
  } else {
    const cA = v.length / 3; v.push(...P(0, 0, a)); const cB = v.length / 3; v.push(...P(0, 0, b));
    for (let i = 0; i < seg; i++) { const j = (i + 1) % seg; t.push(cA, oA + j, oA + i, cB, oB + i, oB + j); }
  }
  const m = { vertices: new Float32Array(v), triangles: new Uint32Array(t) };
